import{_ as c,l as d,o as a,c as n,v as o,p as l,x as t,d as s,i,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"控制器真值表","description":"","frontmatter":{"title":"控制器真值表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/control-truth-table.md","filePath":"cs/control-truth-table.md","lastUpdated":1789023840000}'),A={name:"cs/control-truth-table.md"};function h(E,e,u,m,_,f){const r=d("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="控制器真值表" tabindex="-1">控制器真值表 <a class="header-anchor" href="#控制器真值表" aria-label="Permalink to &quot;控制器真值表&quot;">​</a></h1><div class="epigraph"><p>数据通路上每根选择线都是 opcode 的组合函数；把指令类型排成表，综合成门或 ROM。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/single-cycle-datapath">单周期数据通路</a>把 ALUSrc、RegWrite、MemWrite 等留作端口。本课不重接 ALU 内部，也不从微程序另起。缺口是：<strong>谁根据指令比特驱动这些端口</strong>。答案是组合控制器：真值表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 每类指令需要一组确定的控制：<code>lw</code> 要 MemRead、MemtoReg、ALU 加、RegWrite；<code>sw</code> 要 MemWrite、ALU 加、不写堆；<code>beq</code> 要分支比较、不写堆；R 型要 ALU 功能来自 <code>funct</code>。缺口是把 <code>opcode</code>（及 <code>funct3</code>/<code>funct7</code>）映射到控制向量。ALU 控制可拆成主控给 <code>ALUOp</code>，再由第二张小表译 <code>funct</code>。</p><p>这是组合逻辑，延迟加在取指之后的关键路径上。无关 opcode 若必须 trap，行不能当 \\(X\\)。</p><h3 id="真值表不是-fsm" tabindex="-1">真值表不是 FSM <a class="header-anchor" href="#真值表不是-fsm" aria-label="Permalink to &quot;真值表不是 FSM&quot;">​</a></h3><p>单周期没有「执行阶段状态」：一拍做完，控制器无现态寄存器。把本课画成多圆圈状态图，会与下一课多周期抢层。分支「是否成立」是数据通路比较结果与控制里 Branch 信号相与，仍是同一拍组合。</p><p><span class="marginnote">Patterson/Hennessy 用两级 ALU 控制减少主表列数。Harris 把控制写成 HDL 的 <code>case (opcode)</code>。实现可以是 ROM，内容仍是本课的表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列指令类型 × 控制信号。<code>ALUOp</code> 再进 ALU 控制表出「加/减/与/或/slt」。综合成两级门，满足建立。非法 opcode 输出「异常」线，本课可先接地，<a href="/cs/exception-interrupt-entry">异常课</a>再接。</p>',11)),(a(),l(p,null,{default:t(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22opcode%20%2F%20funct%22%5D%20--%3E%20MAIN%5B%22%E4%B8%BB%E6%8E%A7%E5%88%B6%E7%9C%9F%E5%80%BC%E8%A1%A8%22%5D%0A%20%20MAIN%20--%3E%20ALUC%5B%22ALU%20%E6%8E%A7%E5%88%B6%E5%B0%8F%E8%A1%A8%22%5D%0A%20%20MAIN%20--%3E%20DP%5B%22%E6%95%B0%E6%8D%AE%E9%80%9A%E8%B7%AF%E6%8E%A7%E5%88%B6%E7%BA%BF%22%5D%0A%20%20ALUC%20--%3E%20DP%0A%20%20DP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%9A%E5%91%A8%E6%9C%9F%E6%8B%86%E6%8B%8D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制延迟与指令存储器输出直接相关：opcode 来得晚，控制就晚，往往不在 <code>lw</code> 的内存路径上成为最长，但仍须签核。单周期 CPI 仍为 1，只是 \\(T\\) 含控制。</p><p><code>jal</code>/<code>jalr</code> 的控制容易漏：RegWrite=1、写回值是 PC+4、ALU 或加法器算目标。表要单独一行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把流水线控制按级寄存。不引入微码地址。CSR 指令的控制后置。</p><p>后课默认：单周期控制是 opcode 的组合函数。下一课为缩短 \\(T\\) 把指令拆成多拍，控制变成 FSM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制信号 = 指令类型的真值表（可加 ALU 子表）。</li><li>单周期控制器无状态。</li><li>非法编码与 <code>jal</code> 回写是表上易漏的行。</li><li>出处：Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const b=c(A,[["render",h]]);export{P as __pageData,b as default};
